const root='C:/Dev/EasyEDA/EasyEDA-Project/STM32H747 board';
const project=await eda.dmt_Project.getCurrentProjectInfo();
const path=root+'/output/candidates/adc10-labtool-20261018/libraries/STM32H747_adc10_labtool_new_libraries_20261018.epro2';
const file=await eda.sys_FileSystem.readFileFromFileSystem(path);
if(!file)throw new Error('Reviewed library bundle missing');
const hash=Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',await file.arrayBuffer()))).map(v=>v.toString(16).padStart(2,'0')).join('');
if(hash!=='db7eacfa8c0e683e0832885805592f5d26ba929c6ea5d798fb55c5be1a677145')throw new Error('Reviewed library bundle changed');
const prefix='STM_H747_ADC_LABTOOL_20261018_';
const prior=(await eda.lib_Device.search('',project.uuid,undefined,undefined,1000,1)).filter(x=>x.name?.startsWith(prefix));
if(prior.length)throw new Error('Library import already appears present; inspect, do not reimport');
const imported=await eda.sys_FileManager.importProjectByProjectFile(file,'EasyEDA Pro',{importOption:'ImportDocument'},{operation:'Existing Project',existingProjectUuid:project.uuid});
if(!imported)throw new Error('Import outcome failed/unknown; inspect before any retry');
await eda.dmt_EditorControl.openDocument('a07bf8e4331877a8');
const devices=(await eda.lib_Device.search('',project.uuid,undefined,undefined,1000,1)).filter(x=>x.name?.startsWith(prefix));
const symbols=(await eda.lib_Symbol.search('',project.uuid,undefined,undefined,1000,1)).filter(x=>x.name?.startsWith(prefix));
const footprints=(await eda.lib_Footprint.search('',project.uuid,undefined,1000,1)).filter(x=>x.name?.startsWith(prefix));
const report={projectUuid:project.uuid,packageSha256:hash,imported,devices,symbols,footprints};
const out=root+'/output/validation/native-adc10-labtool-library-import-20261018.json';
if(!await eda.sys_FileSystem.saveFileToFileSystem(out,new Blob([JSON.stringify(report,null,2)]),undefined,false))throw new Error('Import map not saved');
return{path:out,devices:devices.length,symbols:symbols.length,footprints:footprints.length};
